={{ (() => {
  const str = (value) => {
    if (value === undefined || value === null) return '';
    return String(value);
  };

  const safe = (fn, fallback = '') => {
    try {
      const value = fn();
      return value === undefined || value === null ? fallback : value;
    } catch (e) {
      return fallback;
    }
  };

  const unwrapSource = (raw) => {
    if (!raw) return {};
    if (Array.isArray(raw)) return raw[0] || {};
    if (Array.isArray(raw.body)) return raw.body[0] || {};
    if (Array.isArray(raw.data)) return raw.data[0] || {};
    if (Array.isArray(raw.results)) return raw.results[0] || {};
    return raw;
  };

  const makeCell = (value) => {
    return {
      userEnteredValue: {
        stringValue: str(value)
      }
    };
  };

  // Values come from Edit Fields
  const source = unwrapSource($('Edit Fields').first().json);

  // Sheet/table metadata comes from current Get Table ID node output
  const sheet = safe(
    () => $json.sheets.find(sheet => sheet.properties?.title === 'Leads'),
    null
  );

  if (!sheet) {
    throw new Error('Sheet "Leads" not found');
  }

  const table = safe(
    () =>
      (sheet.tables || []).find(table => table.name === 'Leads') ||
      (sheet.tables || []).find(table => table.name === 'Table3') ||
      (sheet.tables || [])[0],
    null
  );

  if (!table) {
    throw new Error('No table found inside sheet "Leads"');
  }

  const values = [
    source.full_name,
    source.jobTitle,
    source.email,
    source.phoneNumber,
    source.phoneSource,
    source.companyName,
    source.industry,
    source.headcount,
    source.leadReceived,
    source.campaign_name,
    source.messageTitle,
    source.messageNumber,
    source.website,
    source.qualification,
    source.responseTime,
    '',
    '',
    '',
    '',
    '',
    '',
    source.reply_message,
    '',
    '',
    source.campaign_id,
    '',
    '',
    source.linkedin_profile_url,
    source.country
  ];

  return JSON.stringify({
    requests: [
      {
        appendCells: {
          sheetId: Number(sheet.properties.sheetId),
          tableId: String(table.tableId),
          rows: [
            {
              values: values.map(value => makeCell(value))
            }
          ],
          fields: 'userEnteredValue'
        }
      }
    ]
  });
})() }}

