={{
  (() => {
    const root = Array.isArray($json) ? $json[0] : $json;
    const messages = Array.isArray(root.messages) ? root.messages : [];

    const sortedMessages = [...messages].sort(
      (a, b) => Number(a.created_at || 0) - Number(b.created_at || 0)
    );

    const latestLeadMessage = [...sortedMessages]
      .filter(msg =>
        msg?.sender?.id &&
        msg?.account_id &&
        String(msg.sender.id) !== String(msg.account_id)
      )
      .sort((a, b) => Number(b.created_at || 0) - Number(a.created_at || 0))[0];

    if (!latestLeadMessage) return '';

    const previousAccountMessage = [...sortedMessages]
      .filter(msg =>
        msg?.sender?.id &&
        msg?.account_id &&
        String(msg.sender.id) === String(msg.account_id) &&
        Number(msg.created_at || 0) < Number(latestLeadMessage.created_at || 0)
      )
      .sort((a, b) => Number(b.created_at || 0) - Number(a.created_at || 0))[0];

    if (!previousAccountMessage) return '';

    const diffMs =
      Number(latestLeadMessage.created_at || 0) -
      Number(previousAccountMessage.created_at || 0);

    const minutes = diffMs / 1000 / 60;

    if (minutes < 15) return 'less than 15 minutes';
    if (minutes < 60) return 'less than 1 hour';
    if (minutes < 720) return 'less than 12 hours';

    return 'another day';
  })()
}}

