        msg?.account_id &&
        String(msg.sender.id) !== String(msg.account_id) &&
        msg?.created_at
      )
      .sort((a, b) => Number(b.created_at || 0) - Number(a.created_at || 0))[0];

    if (!latestLeadMessage) return '';

    return new Date(Number(latestLeadMessage.created_at))
      .toISOString()
      .slice(0, 10);
  })()
}}

