    const lushaRoot = $('Lusha Enrichment').item.json;
    const lusha = Array.isArray(lushaRoot) ? lushaRoot[0] : lushaRoot;

    const lushaCountry = lusha?.body?.results?.[0]?.location?.country;

    if (lushaCountry && String(lushaCountry).trim()) {
      return String(lushaCountry).trim();
    }

    const aimfoxLocation = $('GET lead info Aimfox').item.json.lead?.location?.name || '';

    if (!aimfoxLocation) {
      return '';
    }

    if (!aimfoxLocation.includes(',')) {
      return aimfoxLocation.trim();
    }

    return aimfoxLocation
      .split(',')
      .pop()
      .trim();
  })()
}}

