      const number = phone?.number;
      const type = String(phone?.type || '').trim().toLowerCase();
      const doNotCall = phone?.doNotCall;

      return (
        number &&
        String(number).trim() &&
        type === 'mobile' &&
        (doNotCall === false || String(doNotCall).toLowerCase() === 'false')
      );
    });

    return mobilePhone?.number
      ? String(mobilePhone.number).trim()
      : '';
  })()
}}

={{
  (() => {
    const lushaJson = $('Lusha Enrichment').first().json;
    const lushaBody = lushaJson.body ?? lushaJson;

    // 1. First priority: Lusha company domain, return as-is
    const lushaDomain = lushaBody?.results?.[0]?.company?.domain;

    if (lushaDomain && String(lushaDomain).trim()) {
      return String(lushaDomain).trim();
    }

    // 2. If no Lusha domain, use email logic
    const emails = Array.isArray(lushaBody?.results?.[0]?.emails)
      ? lushaBody.results[0].emails
      : [];

    const lushaWorkEmail = emails.find(item => {
      const emailValue = typeof item === 'string' ? item : item?.email;
      const typeValue = typeof item === 'string' ? '' : item?.type;

      return (
        emailValue &&
        String(emailValue).trim() &&
        String(typeValue || '').trim().toLowerCase() === 'work'
      );
    });

    const workEmailValue =
      typeof lushaWorkEmail === 'string'
        ? lushaWorkEmail
        : lushaWorkEmail?.email;

    const aimfoxEmail = $('GET lead info Aimfox').item.json.lead?.email;

    const email =
      workEmailValue && String(workEmailValue).trim()
        ? String(workEmailValue).trim()
        : aimfoxEmail && String(aimfoxEmail).trim()
          ? String(aimfoxEmail).trim()
          : '';

    // 3. Cut domain from email
    if (!email || !String(email).includes('@')) {
      return '';
    }

    return String(email)
      .split('@')
      .pop()
      .trim();
  })()
}}
